import numpy as np


def day_errors(model, R):
    R = np.asarray(R, dtype=float)
    W_enc, b_enc = np.asarray(model["W_enc"]), np.asarray(model["b_enc"])
    W_dec, b_dec = np.asarray(model["W_dec"]), np.asarray(model["b_dec"])
    Z = (R - b_dec) @ W_enc + b_enc
    X_hat = Z @ W_dec + b_dec
    return ((R - X_hat) ** 2).sum(axis=1)


def threshold_from_val(errors, q):
    e = np.sort(np.asarray(errors, dtype=float))
    return float(e[int(q * len(e)) - 1])

